#!/usr/bin/env bash
# @generated by @metaobjectsdev/pack-cloudflare (cloudflare-deploy) — hand edits are kept by a three-way merge on regeneration; meta verify --codegen checks only the generated parts.
# Deploys app.client acme::docs::Docs.site to one environment, from the model:
#   1. builds it (`npm run build`, skipped with --no-build),
#   2. copies its secrets from the vault (deploy/cloudflare/sync-secrets.sh, skipped with --no-secrets),
#   3. uploads the build to the environment's Pages project and branch, recording the commit.
# Build-time settings are read by the build from this machine's environment; the values the model gives
# are exported first, and a value already in the environment wins.
#
# Needs: what deploy/cloudflare/wrangler.sh needs, and git.
#
#   bash deploy/cloudflare/deploy.sh <environment> [--no-build] [--no-secrets]
set -euo pipefail
cd "$(dirname "$0")/../.."

ENVIRONMENT="${1:-}"
BUILD=1; SECRETS=1
for arg in "${@:2}"; do
  case "$arg" in
    --no-build) BUILD=0 ;;
    --no-secrets) SECRETS=0 ;;
    *) echo 'usage: bash deploy/cloudflare/deploy.sh <environment> [--no-build] [--no-secrets]' >&2; exit 2 ;;
  esac
done
case "$ENVIRONMENT" in
  production)
    # acme::docs::Site.url @default
    export SITE_URL="${SITE_URL:-https://docs.example.com}"
    ;;
  preview)
    # acme::docs::Site.url @default
    export SITE_URL="${SITE_URL:-https://docs.example.com}"
    ;;
  *) echo 'usage: bash deploy/cloudflare/deploy.sh <environment> [--no-build] [--no-secrets] (environments: production, preview)' >&2; exit 2 ;;
esac

if [ "$BUILD" = 1 ]; then
  # build.static pages @command
  npm run build
fi
if [ "$SECRETS" = 1 ]; then bash deploy/cloudflare/sync-secrets.sh "$ENVIRONMENT"; fi

case "$ENVIRONMENT" in
  production)
    bash deploy/cloudflare/wrangler.sh "$ENVIRONMENT" pages deploy dist --project-name=docs-site --branch=main --commit-hash="$(git rev-parse HEAD)"
    ;;
  preview)
    bash deploy/cloudflare/wrangler.sh "$ENVIRONMENT" pages deploy dist --project-name=docs-site --branch=preview --commit-hash="$(git rev-parse HEAD)"
    ;;
  *) echo 'usage: bash deploy/cloudflare/deploy.sh <environment> [--no-build] [--no-secrets] (environments: production, preview)' >&2; exit 2 ;;
esac
